declare const credentialRows: Map<string, { accountId: string; usedAt: number | null; issuedAt: number }>;
export async function consumeCredential(token: string) {
  const credential = credentialRows.get(token);
  if (!credential) throw new Error("CREDENTIAL_MISSING");
  if (credential.usedAt !== null) throw new Error("CREDENTIAL_ALREADY_USED");
  credential.usedAt = Date.now();
  return credential;
}

