declare const hashSecret: (secret: string) => Promise<string>;
declare const accountRows: { update: (id: string, value: object) => Promise<void> };
export async function updateSecret(accountId: string, password: string) {
  const encoded = await hashSecret(password);
  await accountRows.update(accountId, { encoded });
}

